styles.css:
.wp-block-heading { overflow-wrap: break-word; hyphens: auto; text-wrap: balance; } .wp-block-heading:lang(ko), .wp-block-heading:lang(th), .wp-block-heading:lang(lo), .wp-block-heading:lang(my), .wp-block-heading:lang(km), .wp-block-heading:lang(ar), .wp-block-heading:lang(ur) { word-break: keep-all; hyphens: manual; } @keyframes ext-object-drift { from { transform: translateY(10px); } to { transform: translateY(-10px); } } @media (prefers-reduced-motion: reduce) { @keyframes ext-object-drift { from { transform: none; } to { transform: none; } } } .medlux-sticky-header {
    position: fixed !important;
    top: 32px !important;
    left: 0 !important;
    right: 0 !important;
    width: 100% !important;
    z-index: 999999 !important;
}

/* Header height fix */
header .ext-nav-extras { padding-top: 0 !important; padding-bottom: 0 !important; }
header .trp-shortcode-switcher { padding-top: 4px !important; padding-bottom: 4px !important; }
header .alignwide { padding-top: 10px !important; padding-bottom: 10px !important; }

/* Logo always white (theme reverts it to original colours after the hero) */
header.wp-block-template-part .wp-block-site-logo { filter: brightness(0) invert(1) !important; }

/* Main navigation: white links with | separators (desktop) */
header .medlux-main-nav a { color: inherit !important; text-decoration: none !important; }
header .medlux-main-nav a:hover, header .medlux-main-nav .current-menu-item > a { color: #d4a24c !important; }
header .medlux-main-nav .wp-block-navigation__responsive-container:not(.is-menu-open) .wp-block-navigation__container > .wp-block-navigation-item + .wp-block-navigation-item::before { content: "|"; margin-right: 0.9em; }

/* Main navigation dropdowns: dark panel, readable sentence-case items */
header .medlux-main-nav .wp-block-navigation__submenu-container { background-color: rgba(11, 6, 32, 0.96) !important; color: #fefefe !important; border: 1px solid rgba(212, 162, 76, 0.35) !important; border-radius: 8px; padding: 8px 0 !important; min-width: 260px !important; }
header .medlux-main-nav .wp-block-navigation__submenu-container .wp-block-navigation-item__content { text-transform: none; letter-spacing: 0.03em; font-weight: 500; padding: 8px 18px !important; }
header .medlux-main-nav .wp-block-navigation__submenu-container .wp-block-navigation-submenu__toggle { text-transform: none; letter-spacing: 0.03em; font-weight: 500; }

/* Treatment pages (medlux-*) */
.medlux-lead { font-size: 1.25rem; line-height: 1.6; margin-top: var(--wp--preset--spacing--50) !important; }
.medlux-section { margin-top: var(--wp--preset--spacing--60) !important; }
.medlux-treatment-grid, .medlux-steps { gap: 24px !important; margin-top: 24px !important; }
.medlux-card { background: #ffffff; border: 1px solid rgba(212, 162, 76, 0.35); border-radius: 14px; padding: 28px !important; box-shadow: 0 6px 24px -14px rgba(11, 6, 32, 0.25); }
.medlux-card h3 { margin-top: 0 !important; font-size: 1.2rem; }
.medlux-card ul { padding-left: 1.2em; }
.medlux-steps .medlux-card { background: #faf7f1; }
.medlux-cta { margin-top: var(--wp--preset--spacing--60) !important; background: #0b0620; color: #fefefe; border-radius: 16px; padding: 48px 36px !important; text-align: center; }
.medlux-cta h2 { color: #fefefe; }
.medlux-cta .wp-block-buttons { justify-content: center; gap: 16px; }
.medlux-btn-primary .wp-block-button__link { background: #d4a24c !important; color: #0b0620 !important; border-radius: 9999px; padding: 14px 30px; font-weight: 600; }
.medlux-btn-whatsapp .wp-block-button__link { background: transparent !important; color: #fefefe !important; border: 1px solid #d4a24c; border-radius: 9999px; padding: 14px 30px; font-weight: 600; }
.medlux-disclaimer { font-size: 0.8rem; opacity: 0.7; max-width: 640px; margin: 24px auto 0 !important; }
.medlux-intro { margin-top: var(--wp--preset--spacing--50) !important; gap: 40px; }
.medlux-intro .medlux-lead { margin-top: 0 !important; }
.medlux-intro-img img { width: 100%; aspect-ratio: 4 / 3; object-fit: cover; border-radius: 16px; }
/* About Us: slogan line above the intro text */
.medlux-about-slogan { font-family: "Cormorant Garamond", serif; font-style: italic; font-weight: 600; font-size: 1.35rem; line-height: 1.45; color: #b8862e; margin: 0 0 18px !important; }
/* Intro text next to the photo: justified with hyphenation on tablet/desktop; phones stay left-aligned (column too narrow) */
@media (min-width: 782px) { .medlux-intro .medlux-lead { text-align: justify; -webkit-hyphens: auto; hyphens: auto; } }
.medlux-card--photo { overflow: hidden; }
.medlux-card--photo .medlux-card-img { margin: -28px -28px 20px !important; }
.medlux-card--photo .medlux-card-img img { width: 100%; aspect-ratio: 16 / 10; object-fit: cover; display: block; }

/* Home hero buttons: frosted glass background, gold border, white text */
.home .wp-block-cover .wp-block-button__link { background-color: rgba(255, 255, 255, 0.10) !important; -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px); border-color: rgba(240, 196, 106, 0.9) !important; border-width: 2px !important; color: #f0c46a !important; }

/* Home hero headline: stronger shadow and darker backdrop for legibility */
.home .wp-block-cover h1.wp-block-heading { display: table; margin-left: auto !important; margin-right: auto !important; padding: 18px 56px !important; background: radial-gradient(ellipse 50% 50% at 50% 50%, rgba(5, 3, 20, 0.88) 0%, rgba(5, 3, 20, 0.68) 55%, rgba(5, 3, 20, 0) 100%); text-shadow: 0 2px 4px rgba(0, 0, 0, 0.95), 0 4px 16px rgba(0, 0, 0, 0.85), 0 0 36px rgba(0, 0, 0, 0.7) !important; }
@media (max-width: 600px) { .home .wp-block-cover h1.wp-block-heading { display: block; padding: 14px 10px !important; } }
/* Home hero slogan font: Fraunces like all other headings (Source Serif Pro's capital J dropped below the line); calm italics (WONK 0); one line on desktop */
.home .wp-block-cover h1.wp-block-heading { font-family: "Cormorant Garamond", serif !important; font-weight: 600 !important; max-width: none !important; }
.home .wp-block-cover h1.wp-block-heading em { font-variation-settings: "WONK" 0; }

/* Home hero on phones: content higher and buttons closer, so the plane in the background is not hidden behind Explore Travel */
@media (max-width: 600px) { .home .wp-block-cover { align-items: flex-start !important; } .home .wp-block-cover .wp-block-buttons { row-gap: 14px !important; } }

/* Home section intros (Elevate…, Your Medical Journey, Advanced Aesthetics…; not the FAQ column): centred, thin gold line, heading kept smaller than the hero slogan */
.home .ext-section-intro:not(.wp-block-column *) { text-align: center; }
.home .ext-section-intro:not(.wp-block-column *) > * { margin-left: auto !important; margin-right: auto !important; max-width: 720px; }
.home .ext-section-intro:not(.wp-block-column *) h2 { font-size: clamp(1.6rem, 1.1rem + 1.6vw, 2.125rem) !important; }
.home .ext-section-intro:not(.wp-block-column *) h2::after { content: ""; display: block; width: 64px; height: 2px; background: #d4a24c; margin: 18px auto 0; }
.home .ext-section-intro:not(.wp-block-column *) p { font-size: 1.125rem !important; line-height: 1.65; text-wrap: balance; }
@media (max-width: 600px) { .home .ext-section-intro:not(.wp-block-column *) p { font-size: 1.0625rem !important; } }

/* Hospital & Specialist pages */
.medlux-more a { color: #b8862e; font-weight: 600; text-decoration: none; }
.medlux-more a:hover { color: #0b0620; }
.medlux-dept-grid .medlux-card ul { margin: 0; padding-left: 1.1em; }
.medlux-dept-grid .medlux-card li { margin: 4px 0; font-size: 0.95rem; }
.medlux-dept-grid .medlux-card li a { color: #b8862e; font-weight: 600; text-decoration: none; }
.medlux-columns ul { columns: 2; column-gap: 40px; }
@media (max-width: 600px) { .medlux-columns ul { columns: 1; } }

/* Health hub: two large boxes with link lists */
.medlux-hub { gap: 32px !important; margin-top: 24px !important; align-items: stretch !important; }
.medlux-hub-box { display: flex; flex-direction: column; background: #ffffff; border: 1px solid rgba(212, 162, 76, 0.45); border-radius: 18px; padding: 0 32px 32px !important; overflow: hidden; box-shadow: 0 10px 30px -16px rgba(11, 6, 32, 0.3); }
.medlux-hub-box .medlux-hub-img { margin: 0 -32px 8px !important; }
.medlux-hub-box .medlux-hub-img img { width: 100%; aspect-ratio: 16 / 9; object-fit: cover; display: block; }
.medlux-hub-box h2 { font-size: clamp(1.5rem, 2.2vw, 2rem); margin-bottom: 0 !important; }
.medlux-hub-box ul { list-style: none; padding: 0 !important; margin: 8px 0 24px !important; }
.medlux-hub-box li { border-bottom: 1px solid rgba(11, 6, 32, 0.08); margin: 0 !important; }
.medlux-hub-box li a { display: flex; justify-content: space-between; align-items: center; padding: 12px 4px; color: #0b0620; text-decoration: none; font-weight: 500; }
.medlux-hub-box li a::after { content: "→"; color: #b8862e; transition: transform 0.2s ease; }
.medlux-hub-box li a:hover { color: #b8862e; }
.medlux-hub-box li a:hover::after { transform: translateX(4px); }
.medlux-hub-box .wp-block-buttons { margin-top: auto !important; }

/* Why MedLuxLife: dark band, four columns with gold line icons */
.medlux-why { margin-top: var(--wp--preset--spacing--60) !important; background: #0b0620; border-radius: 18px; padding: 48px 40px !important; color: #fefefe; }
.medlux-why h2 { color: #fefefe; text-align: center; margin-bottom: 32px !important; }
.medlux-why-grid { display: grid !important; grid-template-columns: repeat(4, 1fr); gap: 32px; }
.medlux-why-item { border-top: 1px solid rgba(212, 162, 76, 0.5); padding-top: 24px; margin: 0 !important; }
.medlux-why-icon { margin: 0 0 14px !important; }
.medlux-why-icon img { width: 44px; height: 44px; }
.medlux-why-item h3 { color: #f0c46a; font-size: 1.1rem; margin: 0 0 8px !important; }
.medlux-why-item p { color: rgba(254, 254, 254, 0.78); font-size: 0.95rem; line-height: 1.6; margin: 0 !important; }
@media (max-width: 900px) { .medlux-why-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 560px) { .medlux-why-grid { grid-template-columns: 1fr; } .medlux-why { padding: 36px 24px !important; } }

/* Travel hub: alternating image/text rows */
.medlux-rows .medlux-row { background: #ffffff; border: 1px solid rgba(212, 162, 76, 0.45); border-radius: 18px; overflow: hidden; gap: 0 !important; margin-top: 28px !important; box-shadow: 0 10px 30px -18px rgba(11, 6, 32, 0.3); align-items: stretch !important; }
.medlux-row--reverse { flex-direction: row-reverse; }
.medlux-row-media { flex: 0 0 46% !important; position: relative; min-height: 340px; }
.medlux-row-text { flex: 1 1 54% !important; }
.medlux-row-img { position: absolute; inset: 0; margin: 0 !important; }
.medlux-row-img img { width: 100% !important; height: 100% !important; object-fit: cover; display: block; }
.medlux-row-text { padding: 36px 40px !important; }
.medlux-row-text h2 { font-size: clamp(1.5rem, 2.2vw, 2rem); margin-top: 0 !important; }
.medlux-row-text ul { padding-left: 1.1em; }
.medlux-row-text li::marker { color: #d4a24c; }
@media (max-width: 781px) { .medlux-row--reverse { flex-direction: column; } .medlux-row-media { flex-basis: auto !important; min-height: 240px; } .medlux-row-text { padding: 24px !important; } }
.medlux-row-img img { object-position: center 25%; }

/* Header: Free Consultation button */
header .medlux-header-cta { margin: 0 12px 0 0 !important; }
header .medlux-header-cta .wp-block-button__link { background: rgba(255, 255, 255, 0.08) !important; border: 1.5px solid #d4a24c !important; color: #f0c46a !important; border-radius: 9999px !important; padding: 8px 18px !important; font-size: 13px !important; font-weight: 600 !important; letter-spacing: 0.08em; text-transform: uppercase; white-space: nowrap; text-shadow: none !important; transition: background-color 0.2s ease, color 0.2s ease; }
header .medlux-header-cta .wp-block-button__link:hover { background: #d4a24c !important; color: #0b0620 !important; }
@media (max-width: 600px) { header .medlux-header-cta .wp-block-button__link { padding: 6px 12px !important; font-size: 11px !important; letter-spacing: 0.04em; } }
header .medlux-main-nav .wp-block-navigation__container > .wp-block-navigation-item > .wp-block-navigation-item__content,
header .medlux-main-nav .wp-block-navigation__container > .wp-block-navigation-item > .wp-block-navigation-submenu__toggle { white-space: nowrap; letter-spacing: 0.12em; }
@media (min-width: 600px) and (max-width: 1200px) { header .medlux-main-nav .wp-block-navigation__container > .wp-block-navigation-item > .wp-block-navigation-item__content, header .medlux-main-nav .wp-block-navigation__container > .wp-block-navigation-item > .wp-block-navigation-submenu__toggle { letter-spacing: 0.06em; font-size: 13px; } }
header .wp-block-site-logo { flex-shrink: 0 !important; min-width: 72px; }
header .wp-block-site-logo img { min-width: 72px; }
@media (min-width: 600px) and (max-width: 1200px) { header .wp-block-site-title { display: none; } }

/* Free Consultation item: only inside the mobile (hamburger) menu */
header .medlux-main-nav .wp-block-navigation__responsive-container:not(.is-menu-open) .medlux-mobile-only { display: none !important; }
header .medlux-main-nav .is-menu-open .medlux-mobile-only { order: -1; margin: 0 0 12px !important; }
header .medlux-main-nav .is-menu-open .medlux-mobile-only > a { display: inline-block; border: 1.5px solid #d4a24c; border-radius: 9999px; padding: 10px 22px !important; color: #f0c46a !important; font-weight: 600; }

/* Contact Form 7 (MedLuxLife Contact) */
.medlux-form label { display: block; font-weight: 600; font-size: 0.95rem; color: #0b0620; margin-bottom: 16px; }
.medlux-form .medlux-form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 0 20px; }
@media (max-width: 600px) { .medlux-form .medlux-form-row { grid-template-columns: 1fr; } }
.medlux-form input[type=text], .medlux-form input[type=email], .medlux-form input[type=tel], .medlux-form select, .medlux-form textarea { width: 100%; margin-top: 6px; padding: 12px 14px; border: 1px solid rgba(11, 6, 32, 0.2); border-radius: 8px; background: #fff; font: inherit; font-weight: 400; color: #0b0620; box-sizing: border-box; }
.medlux-form input:focus, .medlux-form select:focus, .medlux-form textarea:focus { outline: none; border-color: #d4a24c; box-shadow: 0 0 0 3px rgba(212, 162, 76, 0.2); }
.medlux-form .medlux-form-hint { font-size: 0.85rem; color: rgba(11, 6, 32, 0.6); margin: -6px 0 16px; }
.medlux-form .medlux-consent { font-size: 0.88rem; line-height: 1.5; background: #faf7f1; border: 1px solid rgba(212, 162, 76, 0.4); border-radius: 8px; padding: 14px 16px; margin-bottom: 18px; }
.medlux-form .medlux-consent a { color: #b8862e; font-weight: 600; }
.medlux-form .medlux-consent input[type=checkbox] { width: 18px; height: 18px; margin-right: 8px; vertical-align: -3px; accent-color: #d4a24c; }
.medlux-form .wpcf7-list-item { margin: 0; }
.medlux-form .medlux-consent p, .medlux-form .medlux-consent br { margin: 0; }
.medlux-form .medlux-consent > br, .medlux-form .medlux-consent p:empty { display: none; }
.medlux-form .medlux-form-row > p { display: contents; }
.medlux-form label br { display: none; }
.medlux-form .medlux-form-row br { display: none; }
.medlux-form .wpcf7-form-control-wrap { display: block; }
.medlux-form input[type=submit] { background: #d4a24c; color: #0b0620; border: none; border-radius: 9999px; padding: 14px 34px; font-weight: 700; letter-spacing: 0.05em; cursor: pointer; transition: background-color 0.2s ease; }
.medlux-form input[type=submit]:hover { background: #e8b75c; }
.medlux-form input[type=submit]:disabled { opacity: 0.5; cursor: not-allowed; }

/* Legal pages (Datenschutz, AGB, Impressum) */
.medlux-legal { max-width: 820px; margin-left: auto !important; margin-right: auto !important; padding: 48px 20px 60px; }
.medlux-legal h2 { font-size: 1.35rem; margin-top: 2.2em; margin-bottom: 0.6em; }
.medlux-legal h3 { font-size: 1.1rem; margin-top: 1.4em; }
.medlux-legal p, .medlux-legal li { font-size: 0.98rem; line-height: 1.7; }
.medlux-legal .medlux-legal-note { font-size: 0.88rem; color: rgba(11, 6, 32, 0.6); border-left: 3px solid #d4a24c; padding-left: 12px; }
.medlux-legal a { color: #b8862e; }
mark.medlux-placeholder { background: #fff3c4; color: #7a4b00; padding: 0 4px; border-radius: 3px; }

/* Contact form: health-data consents (shown only for Subject = Health) */
.medlux-form .medlux-health-consent { display: none; }
.medlux-form .medlux-health-consent.is-visible { display: block; }
.medlux-form .medlux-consent-health { border-color: rgba(11, 6, 32, 0.25); background: #f4f2f8; }
.medlux-form .medlux-consent-error { color: #b42318; font-weight: 600; font-size: 0.9rem; margin: -6px 0 14px; }
.medlux-form .medlux-consent-error:empty { display: none; }

/* Footer legal links */
.medlux-footer-legal { font-size: 0.85rem; margin-top: 4px; }
.medlux-footer-legal a { color: inherit; text-decoration: none; }
.medlux-footer-legal a:hover { color: #d4a24c; text-decoration: underline; }
.medlux-footer-legal span { opacity: 0.5; margin: 0 6px; }

/* Contact FAQ */
.medlux-faq .wp-block-accordion-item { border-bottom: 1px solid rgba(11, 6, 32, 0.12); padding-bottom: 12px; }
.medlux-faq .wp-block-accordion-heading { font-size: 1.1rem; line-height: 1.4; margin: 0; }
.medlux-faq .wp-block-accordion-heading__toggle-icon { color: #d4a24c; font-size: 1.4rem; font-weight: 400; }
.medlux-faq .wp-block-accordion-heading__toggle:hover .wp-block-accordion-heading__toggle-title { color: #b8862e; }
.medlux-faq .wp-block-accordion-panel p { font-size: 0.97rem; line-height: 1.65; color: rgba(11, 6, 32, 0.8); margin-top: 8px; }
.medlux-faq .wp-block-accordion-panel a { color: #b8862e; }
.medlux-form .medlux-form-row:first-child label { margin-top: 0; }

/* Header search (icon, expands to the left) */
.medlux-header-search { margin: 0 4px 0 0; }
.medlux-header-search .wp-block-search__inside-wrapper { position: relative; border: 0 !important; padding: 0 !important; background: transparent !important; width: auto !important; }
.medlux-header-search .wp-block-search__button { background: transparent !important; color: #fff !important; border: 0 !important; padding: 8px !important; margin: 0 !important; min-width: 0; box-shadow: none !important; }
.medlux-header-search .wp-block-search__button:hover { color: #d4a24c !important; }
.medlux-header-search .wp-block-search__button svg { width: 24px; height: 24px; fill: currentColor; min-width: 24px; }
.medlux-header-search .wp-block-search__input { position: absolute; right: 100%; top: 50%; transform: translateY(-50%); width: 260px; max-width: 70vw; height: 40px; border-radius: 999px; border: 2px solid #d4a24c !important; background: #fff; color: #0b0620; padding: 0 16px; font-size: 15px; text-transform: none; letter-spacing: normal; font-weight: 400; box-shadow: 0 8px 24px rgba(11, 6, 32, 0.35); }
.medlux-header-search.wp-block-search__searchfield-hidden .wp-block-search__input { width: 0; padding: 0; border-width: 0 !important; opacity: 0; pointer-events: none; }
.medlux-header-search .wp-block-search__input { z-index: 100; }

/* Header fit: compact language switcher below 1500px, hamburger menu below 1100px */
@media (max-width: 1700px) { header .trp-current-language-item__wrapper .trp-language-item-name { display: none !important; } }
@media (min-width: 600px) and (max-width: 1100px) {
  header .medlux-main-nav .wp-block-navigation__responsive-container-open { display: flex !important; }
  header .medlux-main-nav .wp-block-navigation__responsive-container:not(.is-menu-open) { display: none !important; }
  header .medlux-main-nav .medlux-mobile-only { display: list-item !important; }
}

/* Search results page */
body.search .wp-block-post-date { display: none; }
body.search .wp-block-search:not(.medlux-header-search) .wp-block-search__button { background: #d4a24c !important; color: #0b0620 !important; border: 0 !important; }
@media (max-width: 599px) {
  header .ext-nav-extras { display: flex !important; }
  header .ext-nav-extras .medlux-header-cta, header .ext-nav-extras .trp-block-container { display: none !important; }
  .medlux-header-search .wp-block-search__input { width: 220px; }
}
@media (max-width: 1700px) { header .trp-shortcode-switcher__wrapper, header .trp-shortcode-switcher, header .trp-current-language-item__wrapper { min-width: 0 !important; width: auto !important; } header .trp-current-language-item__wrapper { gap: 6px !important; } }
@media (max-width: 599px) {
  header .alignwide > .wp-block-group:has(.medlux-main-nav) { order: 3; }
  header .alignwide > .ext-nav-extras { order: 2; margin-left: auto; }
}
@media (max-width: 1700px) { header .trp-language-switcher { width: auto !important; min-width: 0 !important; } }
@media (max-width: 599px) {
  header .alignwide > .wp-block-group:has(.medlux-main-nav) { padding: 0 !important; margin: 0 0 0 4px !important; }
  header .medlux-header-search { margin: 0; }
}
@media (max-width: 1700px) { header .trp-current-language-item__wrapper { justify-content: flex-start !important; } header .trp-language-item__current { padding-right: 0 !important; width: auto !important; } }

/* Header: centre the main navigation (desktop) */
@media (min-width: 1101px) {
  header .medlux-sticky-header > .wp-block-group.alignwide { display: grid !important; grid-template-columns: 1fr auto 1fr; align-items: center; column-gap: 16px; }
  header .medlux-sticky-header > .wp-block-group.alignwide > .wp-block-group:first-child { justify-self: start; }
  header .medlux-sticky-header > .wp-block-group.alignwide > .wp-block-group:has(.medlux-main-nav) { justify-self: center; margin: 0 !important; padding: 0 !important; }
  header .medlux-sticky-header > .wp-block-group.alignwide > .ext-nav-extras { justify-self: end; }
}
@media (min-width: 1101px) and (max-width: 1700px) {
  header .medlux-main-nav, header .medlux-main-nav .wp-block-navigation-item__content { letter-spacing: 0.08em !important; }
  header .medlux-header-cta { margin-right: 6px !important; }
  header .medlux-header-cta .wp-block-button__link { padding: 7px 14px !important; font-size: 12px !important; letter-spacing: 0.05em !important; }
  header .ext-nav-extras { gap: 6px !important; }
}
@media (min-width: 1101px) and (max-width: 1300px) {
  header .medlux-sticky-header > .wp-block-group.alignwide { column-gap: 8px; }
