  html body.home .wp-site-blocks .mlx-journeys > section:not(.mlx-lang2) { padding: clamp(12px, calc(5.2 * var(--mlx-u) - 19px), 34px) 20px !important; border-radius: 28px;
    border: 1.5px solid rgba(212,162,76,.55); box-shadow: 0 18px 36px -24px rgba(22,20,31,.45); background: #fbf8f2 !important; }
  html body.home .wp-site-blocks .mlx-journeys .ext-section-intro { margin: 0 !important; padding: 0 !important; gap: 0 !important; }
