/* >>> HERO-2026 START: home banner (media 2042 + phone 2043, light logo 2003 = old logo 164; 2026-10-16) – clean photo on Anna's wish: no overlay, no shade band behind the slogan; logo (Emrah's choice B): tight dark shadow around the letters + a very soft dark halo behind it; a tight shadow around the letters and a very soft dark oval under the slogan line so the gold words read on the bright sunset (Anna asked for it); banner fills the first screen on desktop; own crop on phones */
.home main .wp-block-post-content > .ext-hero-section .wp-block-cover > .wp-block-cover__background { opacity: 0 !important; background: none !important; }
.home main .wp-block-post-content > .ext-hero-section .wp-block-cover figure.aligncenter img { filter: drop-shadow(0 0 1px rgba(20, 8, 0, 0.95)) drop-shadow(0 0 3px rgba(20, 8, 0, 0.80)) drop-shadow(0 2px 10px rgba(0, 0, 0, 0.55)) !important; }
/* very soft dark halo behind the logo (fades out well before its edges), drawn under the logo */
.home main .wp-block-post-content > .ext-hero-section .wp-block-cover figure.aligncenter { position: relative; isolation: isolate; }
.home main .wp-block-post-content > .ext-hero-section .wp-block-cover figure.aligncenter::before { content: ""; position: absolute; z-index: -1; left: 50%; top: 50%; width: 175%; height: 150%; transform: translate(-50%, -50%); border-radius: 50%;
  background: radial-gradient(ellipse at center, rgba(12, 8, 30, 0.55) 0%, rgba(12, 8, 30, 0.34) 40%, rgba(12, 8, 30, 0) 70%); pointer-events: none; }
.home main .wp-block-post-content > .ext-hero-section .wp-block-cover h1.wp-block-heading { padding: 20px 110px !important; background: none !important;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.95), 0 0 6px rgba(0, 0, 0, 0.60), 0 2px 16px rgba(0, 0, 0, 0.50) !important; position: relative; isolation: isolate; }
/* very soft dark oval behind the slogan only (fades out before the ends of the line), drawn under the letters */
.home main .wp-block-post-content > .ext-hero-section .wp-block-cover h1.wp-block-heading::before { content: ""; position: absolute; z-index: -1; left: 50%; top: -0.2em; bottom: -0.2em; width: min(100%, 980px); transform: translateX(-50%); border-radius: 50%;
  background: radial-gradient(ellipse at center, rgba(12, 8, 30, 0.50) 0%, rgba(12, 8, 30, 0.32) 42%, rgba(12, 8, 30, 0) 70%); pointer-events: none; }
/* gold words: same deep gold gradient as the hero logo + a tight shadow only around the letters (Anna chose this over an outline) */
.home main .wp-block-post-content > .ext-hero-section .wp-block-cover h1.wp-block-heading mark { background: linear-gradient(180deg, #fee06a 0%, #f2ac30 45%, #d98a1c 75%, #b9670f 100%) !important; -webkit-background-clip: text !important; background-clip: text !important; color: transparent !important; -webkit-text-fill-color: transparent !important; text-shadow: none !important; padding: 0 0.04em;
  filter: drop-shadow(0 0 1px rgba(20, 8, 0, 1)) drop-shadow(0 0 2.5px rgba(20, 8, 0, 0.95)) drop-shadow(0 0 8px rgba(0, 0, 0, 0.60)) !important; }
.home main .wp-block-post-content > .ext-hero-section .wp-block-cover .wp-block-button__link { background-color: rgba(11, 6, 32, 0.50) !important; color: #f2ac30 !important; border-color: #d99c2d !important; box-shadow: 0 6px 16px -8px rgba(0, 0, 0, 0.35) !important; }
@media (min-width: 1100px) {
  /* one screen high (minus the admin bar when logged in), never taller than the photo's own shape allows; on short wide laptops
     (e.g. 1366x613) the photo would have to lose either the plane (under the header) or the two circles, so instead the banner
     grows just enough to keep the whole photo: --mlx-hero-up moves the photo up only until the plane top sits 10px under the
     72px header (plane top = 95/1670 of the width, circle bottom = 838/1670, photo height = 942/1670); the logo, slogan and
     buttons stay centred in the first screen (extra bottom padding), the circles come into view on scrolling */
  .home main .wp-block-post-content > .ext-hero-section .wp-block-cover {
    --mlx-hero-up: max(0px, 5.69vw - 82px);
    --mlx-hero-h: max(min(calc(100svh - var(--wp-admin--admin-bar--height, 0px)), 62vw), calc(50.18vw - var(--mlx-hero-up) + 10px));
    min-height: var(--mlx-hero-h) !important;
    padding-top: calc(var(--wp--preset--spacing--60) + clamp(0px, (100svh - 640px) * 0.2, 90px)) !important;   /* content a bit lower on tall screens, no extra space on short ones */
    padding-bottom: calc(var(--wp--preset--spacing--60) + max(0px, var(--mlx-hero-h) - (100svh - var(--wp-admin--admin-bar--height, 0px)))) !important; }
  /* never move the photo up by more than it overflows (minus 20px for a classic scrollbar, which vw includes), so no gap can open at the bottom */
  .home main .wp-block-post-content > .ext-hero-section .wp-block-cover img.wp-block-cover__image-background { object-position: 50% calc(-1 * min(var(--mlx-hero-up), max(0px, 56.41vw - 20px - var(--mlx-hero-h)))) !important; }
  /* logo, slogan and buttons a bit lower on short screens so the slogan runs below the doctor's neck: slogan centre at least 455/1670 of the
     width into the photo (its centre sits at about 0.6 x screen height - 13px; 0 on tall screens and on 1366x643; the doctor's collar is at 423/1670) */
  .home main .wp-block-post-content > .ext-hero-section .wp-block-cover > .wp-block-cover__inner-container { position: relative; top: min(70px, max(0px, 27.25vw - var(--mlx-hero-up) - (0.6 * (100svh - var(--wp-admin--admin-bar--height, 0px)) - 13px))); }
}
@media (min-width: 782px) and (max-width: 1099px) and (orientation: landscape) {
